-- private

function UIActionDungoenCollectionNode:UpdateCellInfo_()
    local cellData = self:GetCellData()
    
    ---@type RegionEntryVo
    local regionEntryVo = checkTable(cellData.regionEntryVo)
    local idRedPointMap = checkTable(cellData.idRedPointMap)
    local regionEntryId = checkInt(regionEntryVo.uid)
    
    -- update square
    local indexResult = self:GetLuaIndex() % 2
    CfUtils.SetActive(self.controller.gameObject.transform:Find("ImgSquare1"), indexResult == 1)
    CfUtils.SetActive(self.controller.gameObject.transform:Find("ImgSquare2"), indexResult == 0)

    -- check unlock
    local isUnlock, errText = GameUtils.IsUnlockedSingle(regionEntryVo.unlockType, regionEntryVo.unlockNum, regionEntryVo.unlockId)
    CfUtils.SetActive(self.OpenGroup, isUnlock)
    CfUtils.SetActive(self.LockGroup, not isUnlock)
    
    local gray = CfUtils.GetOrAddComponent(self.ImgDungoen, UIGrayGraphics)
    if gray then
        gray:MarkGray(not isUnlock)
    end

    CfUtils.SetImageColor(self.ImgDungoen, isUnlock and UNLOCK_COLOR or LOCKED_COLOR)
    CfUtils.FillImage(self.ImgDungoen, regionEntryVo.bgPathOpen)
    CfUtils.SetActive(self.ImgDungoen, true)

    if isUnlock then
        CfUtils.SetColorString(self.ImgIcon, regionEntryVo.iconColorValue)
        CfUtils.FillText(self.TxtType, regionEntryVo.title)

        -- 实时pvp：时显示时间
        local openStateText = self.OpenGroup.transform:Find("TextOpenState")
        CfUtils.SetActive(openStateText, regionEntryId == Constants.SystemToggleIds.Id2008)
        if regionEntryId == Constants.SystemToggleIds.Id2004 then
            ---@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            local status = checkNumber(playerComponent.playerDojo.consumeCopyActivity.status)
            --local times = checkNumber(playerComponent.playerDojo.consumeCopyActivity.residueNum)
            CfUtils.SetActive(self.equipActivityTrans, status == 1)
            if status == 1 then
                CfUtils.FillText(self.equipActivityTrans:Find("Layout/TextDesc"),   localize('全副武装副本持续中'))
                --CfUtils.FillText(self.equipActivityTrans:Find("Layout/TextDesc"),  localize('活动今日剩余次数: _num_', {_num_ = times}))
            end
        end
        if regionEntryId == Constants.SystemToggleIds.Id2008 then
            ---@type LadderParameterVo
            local vo = CfUtils.GetCfVo(AutoIds.IdSetting2560, 'LadderParameterVo', 2)
            ---@type LadderParameterVo
            local vo2 = CfUtils.GetCfVo(AutoIds.IdSetting2560, 'LadderParameterVo', 3)
            if not vo then
                return
            end
            local startTimes = parse_strings(vo.num, ";")
            local endTimes = parse_strings(vo2.num, ";")
            local str = ""
            for i, v in ipairs(startTimes) do
                local startNumList = string.split(startTimes[i], ":")
                local endNumList = string.split(endTimes[i], ":")
                str = table.concat({ str, startNumList[1], ":", startNumList[2], "-", endNumList[1], ":", endNumList[2] })
                if i < #startTimes then
                    str = table.concat({str, "/"})
                end
            end
            if GameUtils.isZmFunction() then
                local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                ---@type PlayerDojo
                local playerDojo = playerComp.playerDojo
                local serverTimezone = playerDojo:GetServerTimezone() / 3600
                local extra = serverTimezone >= 0 and string.format('+%d', serverTimezone) or string.format('-%d', serverTimezone)
                CfUtils.FillText(openStateText, string.format("%s (UTC%s)", str, extra))
            else
                CfUtils.FillText(openStateText, str)
            end

        end
        -- 红点绑定
        local redPointRootGo  = self.controller.transform:Find("Root").gameObject
        local redPointKeyword = idRedPointMap[regionEntryId]
        CfUtils.SetActive(redPointRootGo.transform:Find("redPoint"), false)
        if redPointKeyword then
            GameUtils.BindRedPoint(redPointKeyword, redPointRootGo, true)
            if GameUtils.GetRedPointNum(redPointKeyword) > 0 then
                CfUtils.SetActive(redPointRootGo.transform:Find("redPoint"), true)
            end
        end

    else
        local redPointRootGo  = self.controller.transform:Find("Root")
        CfUtils.SetActive(redPointRootGo:Find("redPoint"), false)
        errText =  GameUtils.GetUnlockDescr(regionEntryVo.unlockType, regionEntryVo.unlockNum, regionEntryVo.unlockId)
        CfUtils.FillText(self.TxtType1, regionEntryVo.subtitle)
        CfUtils.FillText(self.TxtDesc1, errText)
    end
end


